"""Literal V2 schemas for the pinned SeedVR2 nodes (generated by codegen_schemas.py; see SECURE_CONVERSION.md).

Generated from the pristine define_schema() on a simulated single-CUDA-GPU host (device menus
cuda:0 / none,cpu,cuda:0) with the registry model list only. Never imports the pack.
"""

from comfy_api.latest import io

def SeedVR2VideoUpscaler_schema():
    return io.Schema(
        node_id='SeedVR2VideoUpscaler',
        display_name='SeedVR2 Video Upscaler (v2.5.24)',
        category='SEEDVR2',
        description='SeedVR2 main upscaling node: processes video frames using DiT and VAE models with diffusion-based enhancement. Handles RGB/RGBA formats, maintains temporal consistency across frames, applies color correction, and manages VRAM through intelligent tensor offloading. \n\nRequires DiT and VAE model configurations.',
        inputs=[
            io.Image.Input('image', tooltip='Input video frames as image batch.\nAccepts both RGB (3-channel) and RGBA (4-channel) formats.\nOutput format will match input format.', extra_dict={}),
            io.Custom('SEEDVR2_DIT').Input('dit', tooltip='DiT model configuration from SeedVR2 (Down)Load DiT Model node', extra_dict={}),
            io.Custom('SEEDVR2_VAE').Input('vae', tooltip='VAE model configuration from SeedVR2 (Down)Load VAE Model node', extra_dict={}),
            io.Int.Input('seed', tooltip='Random seed for reproducible generation (default: 42).\nSame seed with same inputs produces identical output.', default=42, min=0, max=4294967295, step=1, extra_dict={}),
            io.Int.Input('resolution', tooltip='Target resolution for the shortest edge in pixels (default: 1080).\nAutomatically maintains aspect ratio of input.\nEven values required for optimal processing.', default=1080, min=16, max=16384, step=2, extra_dict={}),
            io.Int.Input('max_resolution', tooltip='Maximum resolution limit for any dimension (default: 0, no limit).\nIf any edge exceeds this after applying resolution,\nboth dimensions are scaled down proportionally.\nUseful to prevent excessive VRAM usage on extreme aspect ratios.', default=0, min=0, max=16384, step=2, extra_dict={}),
            io.Int.Input('batch_size', tooltip='Number of frames processed together per batch (default: 5).\nMust follow pattern 4n+1: 1, 5, 9, 13, 17, 21, ...\n\n• Higher values: Better temporal consistency and faster processing\n• Lower values: Reduced VRAM usage\n\nIdeally match to shot length for best quality.', default=5, min=1, max=16384, step=4, extra_dict={}),
            io.Boolean.Input('uniform_batch_size', tooltip='Pad final batch to match batch_size (default: False).\nPrevents temporal artifacts caused by small final batch.\nAdd extra compute but recommended for optimal quality.', default=False, extra_dict={}),
            io.Int.Input('temporal_overlap', optional=True, tooltip='Overlapping frames between consecutive batches (default: 0, disabled).\nImproves temporal consistency across batch boundaries through blending.\nValues 1-4 work well for most content.', default=0, min=0, max=16, step=1, extra_dict={}),
            io.Int.Input('prepend_frames', optional=True, tooltip='Number of frames to prepend (reversed from start) before processing (default: 0).\nHelps reduce artifacts at video beginning.\nPrepended frames are automatically removed from final output.', default=0, min=0, max=32, step=1, extra_dict={}),
            io.Combo.Input('color_correction', options=['lab', 'wavelet', 'wavelet_adaptive', 'hsv', 'adain', 'none'], tooltip='Corrects color shifts in upscaled output to match original input (default: lab).\nThe upscaling process may alter colors; this applies color grading to restore them.\n\n• lab: Perceptual color matching with detail preservation (recommended)\n• wavelet: Frequency-based natural colors, preserves fine details\n• wavelet_adaptive: Wavelet base with targeted saturation correction\n• hsv: Hue-conditional saturation matching\n• adain: Statistical style transfer approach\n• none: No color correction applied', default='lab', extra_dict={}),
            io.Float.Input('input_noise_scale', optional=True, tooltip='Input noise injection scale (default: 0.0, disabled).\nAdds controlled variation to input images before encoding.\nRange: 0.0 (no noise) to 1.0 (maximum noise).\nCan help with certain types of artifacts.', default=0.0, min=0.0, max=1.0, step=0.001, extra_dict={}),
            io.Float.Input('latent_noise_scale', optional=True, tooltip="Latent space noise injection scale (default: 0.0, disabled).\nAdds controlled variation during the diffusion process.\nRange: 0.0 (no noise) to 1.0 (maximum noise).\nCan soften details if input_noise_scale doesn't help.", default=0.0, min=0.0, max=1.0, step=0.001, extra_dict={}),
            io.Combo.Input('offload_device', options=['none', 'cpu', 'cuda:0'], optional=True, tooltip="Device for storing intermediate tensors between processing phases (default: cpu).\n• 'none': Keep all tensors on inference device (fastest but highest VRAM usage)\n• 'cpu': Offload to system RAM (recommended for long videos, slower transfers)\n• 'cuda:X': Offload to another GPU (good balance if available, faster than CPU)", default='cpu', extra_dict={}),
            io.Boolean.Input('enable_debug', optional=True, tooltip='Enable detailed debug logging (default: False).\nShows memory usage, timing information, and processing details.\nUseful for troubleshooting errors and performance issues.', default=False, extra_dict={}),
        ],
        outputs=[
            io.Image.Output(tooltip='Upscaled video frames with color correction applied. Format (RGB/RGBA) matches input. Range [0, 1] normalized for ComfyUI compatibility.'),
        ],
    )


def SeedVR2LoadDiTModel_schema():
    return io.Schema(
        node_id='SeedVR2LoadDiTModel',
        display_name='SeedVR2 (Down)Load DiT Model',
        category='SEEDVR2',
        description='Load and configure SeedVR2 DiT (Diffusion Transformer) model for video upscaling. Supports BlockSwap memory optimization for low VRAM systems, model caching for batch processing, multi-GPU offloading, and torch.compile acceleration. \n\nConnect to Video Upscaler node.',
        inputs=[
            io.Combo.Input('model', options=['seedvr2_ema_3b-Q4_K_M.gguf', 'seedvr2_ema_3b-Q8_0.gguf', 'seedvr2_ema_3b_fp8_e4m3fn.safetensors', 'seedvr2_ema_3b_fp16.safetensors', 'seedvr2_ema_7b-Q4_K_M.gguf', 'seedvr2_ema_7b_fp8_e4m3fn_mixed_block35_fp16.safetensors', 'seedvr2_ema_7b_fp16.safetensors', 'seedvr2_ema_7b_sharp-Q4_K_M.gguf', 'seedvr2_ema_7b_sharp_fp8_e4m3fn_mixed_block35_fp16.safetensors', 'seedvr2_ema_7b_sharp_fp16.safetensors'], tooltip='DiT (Diffusion Transformer) model for video upscaling.\nModels automatically download on first use.\nAdditional models can be added to the ComfyUI models folder.', default='seedvr2_ema_3b_fp8_e4m3fn.safetensors', extra_dict={}),
            io.Combo.Input('device', options=['cuda:0'], tooltip='GPU device for DiT model inference (upscaling phase)', default='cuda:0', extra_dict={}),
            io.Int.Input('blocks_to_swap', optional=True, tooltip='Number of transformer blocks to swap between devices for VRAM optimization.\n• 0: Disabled (default)\n• 3B model: 0-32 blocks\n• 7B model: 0-36 blocks\n\nRequires offload_device to be set and different from device.\nNot available on macOS (unified memory architecture).', default=0, min=0, max=36, step=1, extra_dict={}),
            io.Boolean.Input('swap_io_components', optional=True, tooltip='Offload input/output embeddings and normalization layers to reduce VRAM.\nRequires offload_device to be set and different from device.\nNot available on macOS (unified memory architecture).', default=False, extra_dict={}),
            io.Combo.Input('offload_device', options=['none', 'cpu', 'cuda:0'], optional=True, tooltip="Device to offload DiT model when not actively processing.\n• 'none': Keep model on inference device (default, fastest)\n• 'cpu': Offload to system RAM (reduces VRAM usage)\n• 'cuda:X': Offload to another GPU (good balance if available)\n\nRequired for BlockSwap (blocks_to_swap or swap_io_components).", default='none', extra_dict={}),
            io.Boolean.Input('cache_model', optional=True, tooltip='Keep DiT model loaded on offload_device between workflow runs.\nUseful for batch processing to avoid repeated loading.\nRequires offload_device to be set.', default=False, extra_dict={}),
            io.Combo.Input('attention_mode', options=['sdpa', 'flash_attn_2', 'flash_attn_3', 'sageattn_2', 'sageattn_3'], optional=True, tooltip='Attention computation backend:\n• sdpa: PyTorch scaled_dot_product_attention (default, stable, always available)\n• flash_attn_2: Flash Attention 2 (Ampere+, requires flash-attn package)\n• flash_attn_3: Flash Attention 3 (Hopper+, requires flash-attn with FA3 support)\n• sageattn_2: SageAttention 2 (requires sageattention package)\n• sageattn_3: SageAttention 3 (Blackwell/RTX 50xx only, requires sageattn3 package)\n\nSDPA is recommended - stable and works everywhere.\nFlash Attention and SageAttention provide speedup through optimized CUDA kernels on compatible GPUs.', default='sdpa', extra_dict={}),
            io.Custom('TORCH_COMPILE_ARGS').Input('torch_compile_args', optional=True, tooltip='Optional torch.compile optimization settings from SeedVR2 Torch Compile Settings node.\nProvides 20-40% speedup with compatible PyTorch 2.0+ and Triton installation.', extra_dict={}),
        ],
        outputs=[
            io.Custom('SEEDVR2_DIT').Output(tooltip='DiT model configuration containing model path, device settings, BlockSwap parameters, and compilation options. Connect to Video Upscaler node.'),
        ],
    )


def SeedVR2LoadVAEModel_schema():
    return io.Schema(
        node_id='SeedVR2LoadVAEModel',
        display_name='SeedVR2 (Down)Load VAE Model',
        category='SEEDVR2',
        description='Load and configure SeedVR2 VAE (Variational Autoencoder) for encoding/decoding video frames to/from latent space. Supports tiled processing to handle high resolutions on limited VRAM, model caching, multi-GPU offloading, and torch.compile acceleration. \n\nConnect to Video Upscaler node.',
        inputs=[
            io.Combo.Input('model', options=['ema_vae_fp16.safetensors'], tooltip='VAE (Variational Autoencoder) model for encoding/decoding.\nModels automatically download on first use.\nAdditional models can be added to the ComfyUI models folder.', default='ema_vae_fp16.safetensors', extra_dict={}),
            io.Combo.Input('device', options=['cuda:0'], tooltip='GPU device for VAE model inference (encoding/decoding phases)', default='cuda:0', extra_dict={}),
            io.Boolean.Input('encode_tiled', optional=True, tooltip='Enable tiled encoding to reduce VRAM usage during the encoding phase', default=False, extra_dict={}),
            io.Int.Input('encode_tile_size', optional=True, tooltip='Encoding tile size in pixels (default: 1024).\nApplied to both height and width.\nLower values reduce VRAM usage but may increase processing time.\nOnly used when encode_tiled is enabled.', default=1024, min=64, step=32, extra_dict={}),
            io.Int.Input('encode_tile_overlap', optional=True, tooltip='Pixel overlap between encoding tiles (default: 128).\nReduces visible seams between tiles through blending.\nHigher values improve quality but slow processing.\nOnly used when encode_tiled is enabled.', default=128, min=0, step=32, extra_dict={}),
            io.Boolean.Input('decode_tiled', optional=True, tooltip='Enable tiled decoding to reduce VRAM usage during the decoding phase', default=False, extra_dict={}),
            io.Int.Input('decode_tile_size', optional=True, tooltip='Decoding tile size in pixels (default: 1024).\nApplied to both height and width.\nLower values reduce VRAM usage but may increase processing time.\nOnly used when decode_tiled is enabled.', default=1024, min=64, step=32, extra_dict={}),
            io.Int.Input('decode_tile_overlap', optional=True, tooltip='Pixel overlap between decoding tiles (default: 128).\nReduces visible seams between tiles through blending.\nHigher values improve quality but slow processing.\nOnly used when decode_tiled is enabled.', default=128, min=0, step=32, extra_dict={}),
            io.Combo.Input('tile_debug', options=['false', 'encode', 'decode'], optional=True, tooltip="Tile debug visualization mode:\n• 'false': No visualization overlay (default)\n• 'encode': Show encoding tile boundaries\n• 'decode': Show decoding tile boundaries\n\nOnly works when respective tiling is enabled.", default='false', extra_dict={}),
            io.Combo.Input('offload_device', options=['none', 'cpu', 'cuda:0'], optional=True, tooltip="Device to offload VAE model when not actively processing.\n• 'none': Keep model on inference device (default, fastest)\n• 'cpu': Offload to system RAM (reduces VRAM usage)\n• 'cuda:X': Offload to another GPU (good balance if available)", default='none', extra_dict={}),
            io.Boolean.Input('cache_model', optional=True, tooltip='Keep VAE model loaded on offload_device between workflow runs.\nUseful for batch processing to avoid repeated loading.\nRequires offload_device to be set.', default=False, extra_dict={}),
            io.Custom('TORCH_COMPILE_ARGS').Input('torch_compile_args', optional=True, tooltip='Optional torch.compile optimization settings from SeedVR2 Torch Compile Settings node.\nProvides 15-25% speedup with compatible PyTorch 2.0+ and Triton installation.', extra_dict={}),
        ],
        outputs=[
            io.Custom('SEEDVR2_VAE').Output(tooltip='VAE model configuration containing model path, device settings, tiling parameters, and compilation options. Connect to Video Upscaler node.'),
        ],
    )


def SeedVR2TorchCompileSettings_schema():
    return io.Schema(
        node_id='SeedVR2TorchCompileSettings',
        display_name='SeedVR2 Torch Compile Settings',
        category='SEEDVR2',
        description='Configure SeedVR2 torch.compile optimization for 20-40% DiT speedup and 15-25% VAE speedup. Trades longer first-run compilation time for faster inference.\n\nConnect to DiT and/or VAE model loaders. Requires PyTorch 2.0+ and Triton for inductor backend.',
        inputs=[
            io.Combo.Input('backend', options=['inductor', 'cudagraphs'], tooltip='Compilation backend:\n• inductor: Full optimization with Triton kernel generation and fusion (recommended)\n• cudagraphs: Lightweight wrapper using CUDA graphs, no kernel optimization', default='inductor', extra_dict={}),
            io.Combo.Input('mode', options=['default', 'reduce-overhead', 'max-autotune', 'max-autotune-no-cudagraphs'], tooltip='Optimization level (compilation time vs runtime performance):\n• default: Fast compilation with good speedup (recommended for development)\n• reduce-overhead: Lower overhead, optimized for smaller models\n• max-autotune: Slowest compilation, best runtime performance (recommended for production)\n• max-autotune-no-cudagraphs: Like max-autotune but without CUDA graphs', default='default', extra_dict={}),
            io.Boolean.Input('fullgraph', tooltip='Compile entire model as single graph without breaks.\n• False: Allow graph breaks for better compatibility (default)\n• True: Enforce no breaks for maximum optimization (may fail with dynamic shapes)', default=False, extra_dict={}),
            io.Boolean.Input('dynamic', tooltip='Handle varying input shapes without recompilation.\n• False: Specialize for exact input shapes (default)\n• True: Create dynamic kernels that adapt to shape variations\n\nEnable when processing different resolutions or batch sizes.', default=False, extra_dict={}),
            io.Int.Input('dynamo_cache_size_limit', tooltip='Maximum cached compiled versions per function (default: 64).\nControls how many shape variations to compile before stopping.\n\n• Increase: When processing many different input shapes (more memory usage)\n• Decrease: When recompilation cost outweighs benefits (faster fallback to eager)', default=64, min=0, max=1024, step=1, extra_dict={}),
            io.Int.Input('dynamo_recompile_limit', tooltip="Maximum recompilation attempts before fallback to eager mode (default: 128).\nSafety limit to prevent infinite compilation loops.\n\nOnly increase if you see 'hit config.recompile_limit' warnings and have bounded shape variations.", default=128, min=0, max=1024, step=1, extra_dict={}),
        ],
        outputs=[
            io.Custom('TORCH_COMPILE_ARGS').Output(tooltip='torch.compile optimization settings including backend, mode, and Dynamo configuration. Connect to DiT and/or VAE model loader nodes.'),
        ],
    )
